-- Stage 7: whiteboard trace templates and many more SYSTEM exercise variations.
-- The child app draws a dotted outline of trace_template on the board for the child to trace.
ALTER TABLE whiteboard_exercise_configs ADD COLUMN trace_template VARCHAR(16);
ALTER TABLE whiteboard_exercise_configs ADD CONSTRAINT chk_whiteboard_config_trace_template
    CHECK (trace_template IS NULL OR trace_template IN ('sun', 'house', 'fish', 'star', 'flower', 'heart'));

